begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, auth, extensions;
select no_plan();
create temporary table contact_fixture(doc jsonb);
insert into contact_fixture values ('{"meta":{"productionContacts":[{"id":"crew-1","type":"crew","name":"Example crew","role":"Camera","phone":"555-0100","email":"crew@example.test","callTime":"8:15 AM","reportTo":"Basecamp"}],"callsheet":{"productionOffice":"Office","hospitalPhone":"555-0199","hospitalNotes":"Main entrance","advanceSchedule":"Day two"}},"rows":[]}');
select lives_ok($$select private.validate_schedule_document('{"meta":{},"rows":[]}',1)$$,'Legacy document still accepted');
select lives_ok($$select private.validate_schedule_document(doc,1) from contact_fixture$$,'Production contacts and expanded call sheet accepted');
select throws_ok($$select private.validate_schedule_document(jsonb_set(doc,'{meta,productionContacts,0,type}','"admin"'),1) from contact_fixture$$,'PT400','Invalid schedule document','Invalid contact type rejected');
select throws_ok($$select private.validate_schedule_document(doc #- '{meta,productionContacts,0,role}',1) from contact_fixture$$,'PT400','Invalid schedule document','Missing required contact string rejected');
select throws_ok($$select private.validate_schedule_document(jsonb_set(doc,'{meta,productionContacts,0,callTime}','"25:00"'),1) from contact_fixture$$,'PT400','Invalid schedule document','Invalid call time rejected');
select throws_ok($$select private.validate_schedule_document(jsonb_set(doc,'{meta,productionContacts,0,secret}','"not accepted"'),1) from contact_fixture$$,'PT400','Invalid schedule document','Unknown contact fields rejected');
select throws_ok($$select private.validate_schedule_document(jsonb_set(doc,'{meta,productionContacts}',(doc#>'{meta,productionContacts}')||(doc#>'{meta,productionContacts}')),1) from contact_fixture$$,'PT400','Invalid schedule document','Duplicate contacts rejected');
select throws_ok($$select private.validate_schedule_document(jsonb_set(doc,'{meta,productionContacts,0,phone}','null'),1) from contact_fixture$$,'PT400','Invalid schedule document','Null contact strings rejected');
select ok(not (private.client_projection(doc)->'meta' ? 'productionContacts'),'Public client projection excludes contact directory') from contact_fixture;
select ok(not (private.client_projection(doc)->'meta' ? 'callsheet'),'Public client projection excludes call sheet') from contact_fixture;
select ok(not has_function_privilege('anon','private.validate_schedule_document(jsonb,integer)','EXECUTE'),'Validator not exposed to anonymous users');
select * from finish();
rollback;
